'use strict';class GeofenceSyncQueue{constructor(opts={}){this._opts=Object.assign({visitId:null,geofenceId:null,apiBase:'/crm/api/geofence.php',csrfToken:'',flushIntervalSec:30,maxBatchSize:50,onFlush:null,onFlushFail:null,},opts);this._queue=[];this._inflight=!1;this._running=!1;this._timerId=null;this._backoffMs=0;this._totalSent=0;this._totalFailed=0;this._retryQueue=[]}
start(){if(this._running)return;this._running=!0;this._scheduleFlush();console.debug('[GeofenceSyncQueue] Started. Interval:',this._opts.flushIntervalSec,'s')}
stop(){this._running=!1;if(this._timerId){clearTimeout(this._timerId);this._timerId=null}
this.flush()}
enqueue(sample){this._queue.push(sample);if(this._queue.length>=this._opts.maxBatchSize&&!this._inflight){this.flush()}}
get queueLength(){return this._queue.length+this._retryQueue.length}
flush(){if(this._inflight)return Promise.resolve({skipped:!0});const combined=[...this._retryQueue,...this._queue];this._retryQueue=[];this._queue=[];if(!combined.length)return Promise.resolve({inserted:0,skipped:0});if(!navigator.onLine){this._retryQueue=combined;console.debug('[GeofenceSyncQueue] Offline — deferred',combined.length,'samples');return Promise.resolve({deferred:combined.length})}
const batches=[];for(let i=0;i<combined.length;i+=this._opts.maxBatchSize){batches.push(combined.slice(i,i+this._opts.maxBatchSize))}
this._inflight=!0;return this._sendBatches(batches).then(result=>{this._inflight=!1;this._backoffMs=0;this._totalSent+=result.inserted;if(typeof this._opts.onFlush==='function')this._opts.onFlush(result);return result}).catch(err=>{this._inflight=!1;this._retryQueue=[...combined,...this._retryQueue];this._totalFailed++;this._backoffMs=Math.min(this._backoffMs?this._backoffMs*2:5000,120000);console.warn('[GeofenceSyncQueue] Flush failed, backing off',this._backoffMs/1000,'s. Queued:',this._retryQueue.length);if(typeof this._opts.onFlushFail==='function')this._opts.onFlushFail(err);return{error:err.message}})}
_sendBatches(batches){let totalInserted=0;let totalSkipped=0;const sendNext=(i)=>{if(i>=batches.length){return Promise.resolve({inserted:totalInserted,skipped:totalSkipped})}
return this._sendBatch(batches[i]).then(res=>{totalInserted+=res.inserted||0;totalSkipped+=res.skipped||0;return sendNext(i+1)})};return sendNext(0)}
_sendBatch(samples){const body=JSON.stringify({action:'sync_samples',csrf_token:this._opts.csrfToken,visit_id:this._opts.visitId,geofence_id:this._opts.geofenceId,samples,});return fetch(this._opts.apiBase,{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body,}).then(r=>{if(!r.ok)throw new Error('HTTP '+r.status);return r.json()}).then(data=>{if(!data.success)throw new Error(data.error||'Sync error');console.debug('[GeofenceSyncQueue] Batch sent:',data.inserted,'inserted,',data.skipped,'skipped');return data})}
_scheduleFlush(){if(!this._running)return;const delay=this._backoffMs>0?this._backoffMs:this._opts.flushIntervalSec*1000;this._timerId=setTimeout(()=>{this.flush().finally(()=>this._scheduleFlush())},delay)}
get stats(){return{queued:this.queueLength,totalSent:this._totalSent,totalFailed:this._totalFailed,backoffMs:this._backoffMs,}}}
if(typeof module!=='undefined'&&module.exports){module.exports={GeofenceSyncQueue}}else{window.GeofenceSyncQueue=GeofenceSyncQueue}